        node ← root
        // Selection (PUCT/UCB with learned/adaptive priors)
        while node.expanded and not is_terminal(node.partial, problem)
            node ← argmax_child(node.children, UCB_PUCT(child, node, params))
        // Expansion (add or sample promising actions)
        if not is_terminal(node.partial, problem)
            actions ← sample_actions(node.partial, problem, params)      // heuristics + exploration
            expand(node, actions)
            node ← choose_one_new_child(node)                           // expansion point for rollout
        // Rollout: construct a complete solution using adaptive heuristic policy
        sim ← rollout_from(node.partial, problem, params)               // greedy/softmax over heuristics
        sim ← repair_and_complete(sim, problem, params)                 // enforce feasibility (e.g., capacities, precedence)
        value ← evaluate(sim, problem)                                  // objective (distance, makespan, ...)
        // Backpropagation: propagate value and update node priors/statistics
        backpropagate(node, value)
        if value < evaluate(best, problem) then best ← sim              // keep best found solution
        // Intensification: occasional local large-neighborhood search on best
        if intensify_trigger(params) then best ← LNS_destroy_repair(best, problem, params)
        // Adaptation: update rollout policy priors from accumulated statistics
        adapt_priors_and_policy(root, params)
    return best

