def tour_length(tour: List[int]) -> float:
    if not tour:
        return 0.0
    arr = np.asarray(tour, dtype=int)
    # vectorized sum of distances along the tour including return to start
    dist = self.distance_matrix[arr, np.roll(arr, -1)].sum()
    return float(dist)

